"""Native nonoverlapping count, clipped bounds and builtin method identity."""
import ast
import shutil
import unittest
from py2fastrust import transpile,TranspileOptions
from py2fastrust.frontend import build_program
from tests import test_native_frame_splits as text_helpers


class CountCapabilityTests(unittest.TestCase):
    def test_original_ast_and_scope_nodes_are_retained(self):
        from py2fastrust.native_classes import try_generate_classes
        source="class Box:\n def run(self,text):return text.count('a',0,None)\nprint(Box().run('aba'))\n"
        unit=build_program(source,'main.py').main
        before=ast.dump(unit.tree,include_attributes=True);nodes=tuple(ast.walk(unit.tree))
        self.assertIsNotNone(try_generate_classes(source,'main.py','i64',unit=unit))
        self.assertEqual(ast.dump(unit.tree,include_attributes=True),before)
        self.assertEqual(tuple(ast.walk(unit.tree)),nodes)

    def test_existing_static_text_and_list_count_paths_are_retained(self):
        from py2fastrust.native_frame_selection import select_frames
        for source in ["text=input()\nprint(text.count('a'),text.count('',0,None))\n",
                       "values=[1,2,1]\nprint(values.count(1))\n",
                       "values=list(map(int,input().split()))\nprint(sum(values))\n"]:
            self.assertFalse(select_frames(build_program(source,'main.py').main).required)

    def test_custom_slice_index_protocol_has_a_positioned_diagnostic(self):
        source="class Position:\n def __index__(self):return 1\nclass Box:\n def run(self):return 'abc'.count('b',Position())\nprint(Box().run())\n"
        for mode in ('i64','i128','bigint'):
            result=transpile(source,TranspileOptions(integer=mode))
            self.assertFalse(result.success)
            self.assertEqual(result.diagnostics[0].code,'E006')
            self.assertGreater(result.diagnostics[0].line,0)
            self.assertIn('__index__',result.diagnostics[0].message)

    def test_custom_byte_pattern_protocol_has_a_positioned_diagnostic(self):
        source="class Pattern:pass\nclass Box:\n def run(self):return b'abc'.count(Pattern())\nprint(Box().run())\n"
        for mode in ('i64','i128','bigint'):
            result=transpile(source,TranspileOptions(integer=mode))
            self.assertFalse(result.success)
            self.assertEqual(result.diagnostics[0].code,'E006')
            self.assertGreater(result.diagnostics[0].line,0)
            self.assertIn('buffer protocol',result.diagnostics[0].message)


@unittest.skipUnless(shutil.which('rustc'),'rustc is required')
class CountExecutionTests(unittest.TestCase):
    exercise=text_helpers.SplitExecutionTests.exercise

    def test_text_nonoverlap(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  for pattern in ['', 'a','aa','aaa','b','aaaaaa']:\n   print(self.text.count(pattern))\nBox('aaaaa').run()\n")

    def test_bytes_nonoverlap(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  for pattern in [b'',b'a',b'aa',b'aaa',b'b',b'aaaaaa']:\n   print(self.text.count(pattern))\nBox(b'aaaaa').run()\n")

    def test_text_bounds(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  for pattern in ['', 'a','aa','b']:\n   for start in [None,-20,-5,-1,0,1,5,6,20]:\n    for stop in [None,-20,-1,0,2,5,20]:print(self.text.count(pattern,start,stop))\nBox('aaaaa').run()\n")

    def test_bytes_bounds(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  for pattern in [b'',b'a',b'aa',b'b']:\n   for start in [None,-20,-5,-1,0,1,5,6,20]:\n    for stop in [None,-20,-1,0,2,5,20]:print(self.text.count(pattern,start,stop))\nBox(b'aaaaa').run()\n")

    def test_integer_byte_patterns(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  for pattern in [0,1,97,98,255,False,True]:print(self.text.count(pattern),self.text.count(pattern,1,-1))\nBox(b'\\x00ab\\xff\\x01a\\x00').run()\n")

    def test_unicode_count(self):
        self.exercise("# pytors: --string-mode unicode\nclass Box:\n def __init__(self,text):self.text=text\n def run(self):\n  for pattern in ['', '猫','猫犬','é','́','海']:\n   for start in [None,-20,-2,0,1,3,9,20]:print(self.text.count(pattern,start),self.text.count(pattern,start,-1))\nBox('猫犬猫éé猫').run()\n")

    def test_mixed_domains(self):
        self.exercise("class Box:\n def run(self,text,pattern):return text.count(pattern)\nb=Box()\nprint(b.run('aaaaa','aa'))\nprint(b.run(b'aaaaa',b'aa'))\n")

    def test_projected_rows(self):
        self.exercise("rows=[('aaaaa','aa'),('abc','')]\nfor text,pattern in rows:print(text.count(pattern))\n")

    def test_optional_bounds(self):
        self.exercise("class Box:\n def run(self,text,start,stop):return text.count('a',start,stop)\nfor start in [None,0,True,-2]:\n for stop in [None,False,4]:print(Box().run('ababa',start,stop))\n")

    def test_argument_order(self):
        self.exercise("class Box:\n def __init__(self):self.text='ababa'\n def pattern(self):\n  print('pattern')\n  self.text='changed'\n  return 'a'\n def start(self):\n  print('start')\n  return 1\n def end(self):\n  print('end')\n  return 5\n def run(self):print(self.text.count(self.pattern(),self.start(),self.end()),self.text)\nBox().run()\n")

    def test_ordinary_text(self):
        self.exercise("text=input()\nprint(text.count('a'),text.count(''),text.count('aa',1,-1))\n",data='aaaaa\n')

    def test_ordinary_bytes(self):
        self.exercise("import sys\ntext=sys.stdin.buffer.readline().rstrip(b'\\n')\nprint(text.count(97),text.count(b''),text.count(b'aa',1,-1))\n",data='aaaaa\n')

    def test_empty_windows(self):
        self.exercise("class Box:\n def run(self,text,pattern):\n  for start in [None,-1,0,1,2]:\n   for stop in [None,-1,0,1,2]:print(text.count(pattern,start,stop))\nb=Box()\nb.run('','')\nb.run(b'',b'')\nb.run(b'',0)\n")

    def test_combined_operations(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.replace('aa','b').count('b'),self.text.find('aa'),self.text.rfind('aa'),self.text.strip('a'))\nBox('aaaaa').run()\n")

    def test_text_integer_pattern(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.count(97))\nBox('aaaaa').run()\n")

    def test_text_none_pattern(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.count(None))\nBox('aaaaa').run()\n")

    def test_text_bytes_pattern(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.count(b'a'))\nBox('aaaaa').run()\n")

    def test_bytes_text_pattern(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(b'abc'.count('a'))\nBox('aaaaa').run()\n")

    def test_bytes_none_pattern(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(b'abc'.count(None))\nBox('aaaaa').run()\n")

    def test_bytes_bad_integer(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(b'abc'.count(256))\nBox('aaaaa').run()\n")

    def test_float_start(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.count('a',1.5))\nBox('aaaaa').run()\n")

    def test_text_bad_pattern_and_start(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.count(7,1.5))\nBox('aaaaa').run()\n")

    def test_bytes_bad_pattern_and_start(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(b'abc'.count('a',1.5))\nBox('aaaaa').run()\n")

    def test_keyword_start(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.count('a',start=1))\nBox('aaaaa').run()\n")

    def test_missing_pattern(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.count())\nBox('aaaaa').run()\n")

    def test_too_many_arguments(self):
        self.exercise("class Box:\n def __init__(self,text):self.text=text\n def run(self):\n  print(self.text.count('a',0,1,2))\nBox('aaaaa').run()\n")

