    def test_start_width_normalization(self):
        self.exercise("class Box:\n def run(self):return 'abc'.count('',1<<63)\nprint(Box().run())\n",expected_by_integer={'i64': ('4\n', '', 0)})

    def test_end_width_normalization(self):
        self.exercise("class Box:\n def run(self):return b'abc'.count(97,0,1<<63)\nprint(Box().run())\n",expected_by_integer={'i64': ('0\n', '', 0)})

    def test_integer_needle_width_normalization(self):
        self.exercise("class Box:\n def run(self):return b'\\x00a'.count(1<<64)\nprint(Box().run())\n",expected_by_integer={'i64': ('1\n', '', 0)})

    def test_negative_start_width_normalization(self):
        self.exercise("class Box:\n def run(self):return 'abc'.count('a',-((1<<63)+1))\nprint(Box().run())\n",expected_by_integer={'i64': ('0\n', '', 0)})

    def test_user_count_method(self):
        self.exercise('class Box:\n def __init__(self):self.n=0\n def count(self,value):\n  self.n+=value\n  return self.n\nb=Box()\nprint(b.count(4),b.count(7))\n')

    def test_byte_adversarial_prefix(self):
        self.exercise("import sys\ntext=sys.stdin.buffer.readline().rstrip(b'\\n')\nneedle=sys.stdin.buffer.readline().rstrip(b'\\n')\nprint(text.count(needle))\n",data='\\n')
